classDiagram class Task { - task_id: str - type: str - duration_minutes: int - frequency: str - priority: int - deadline: Optional~datetime~ - preferred_time_window: Optional~str~ - assigned: bool - notes: Optional~str~ - status: str + is_overdue(current_time) bool + next_occurrence() Optional~Task~ + mark_done() Optional~Task~ + reschedule(new_deadline) + score() float + to_display() str + start_time() Optional~str~ + as_time_interval() Optional~tuple[time, time]~ }
class Pet { - name: str - species: str - breed: Optional~str~ - age: Optional~int~ - health_conditions: List~str~ - daily_needs: Dict~str, str~ - energy_level: Optional~str~ - tasks: List~Task~ + needs() Dict~str, str~ + add_task(task) + remove_task(task_id) + get_tasks() List~Task~ + get_pending_tasks() List~Task~ + is_high_risk() bool + describe() str }
class Owner { - name: str - contact_info: Optional~str~ - daily_availability: Dict~str, int~ - preferences: Dict~str, str~ - max_daily_tasks: Optional~int~ - pets: List~Pet~ + add_pet(pet) + remove_pet(pet_name) + get_pets() List~Pet~ + get_all_tasks() List~Task~ + get_pending_tasks() List~Task~ + set_availability(availability) + update_preference(key, value) + can_do_task(task) bool + summary() str }
class Scheduler { - owner: Owner - schedules: Dict~date, Schedule~ + create_schedule(date_, pet) Schedule + get_schedule(date_) Optional~Schedule~ + organize_tasks(date_) + find_task_and_pet(task_id) Optional~tuple[Task, Pet]~ + mark_task_complete(task_id) Optional~Task~ + manage_tasks() + sort_by_time(tasks) List~Task~ + filter_tasks(pet_name, status) List~Task~ + find_conflicts(task, tasks) List~Task~ + add_recurring_task(task, occurrences) List~Task~ + get_all_scheduled_tasks() List~Task~ }
class Schedule { - date: date - owner: Optional~Owner~ - pet: Optional~Pet~ - tasks: List~Task~ - total_time: int - constraints_applied: Dict~str, str~ - explanation: str + add_task(task) + remove_task(task_id) + generate_plan(constraints) + validate() bool + get_timeline() List~str~ + explain() str + adjust_for_overflow() + get_conflict_warnings() List~str~ }
Owner "1" *-- "1..*" Pet : owns Pet "1" *-- "0..*" Task : has Scheduler "1" -- "1" Owner : manages Scheduler "1" o-- "0..*" Schedule : creates Schedule "1" o-- "1" Owner : references Schedule "0..*" o-- "0..1" Pet : references Schedule "1" *-- "0..*" Task : contains
